import { test, expect } from '@playwright/test';

test.describe('Table Data Verification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
  });

  test('should verify table #table1 header row contains correct column headings', async ({ page }) => {
    const table = page.locator('#table1');

    const headerCells = table.locator('thead th');
    const headerCount = await headerCells.count();

    expect(headerCount).toBe(4);

    const lastNameHeader = table.locator('thead th').filter({ hasText: 'Last Name' });
    const firstNameHeader = table.locator('thead th').filter({ hasText: 'First Name' });
    const emailHeader = table.locator('thead th').filter({ hasText: 'Email' });
    const dueHeader = table.locator('thead th').filter({ hasText: 'Due' });

    await expect(lastNameHeader).toBeVisible();
    await expect(firstNameHeader).toBeVisible();
    await expect(emailHeader).toBeVisible();
    await expect(dueHeader).toBeVisible();
  });

  test('should verify table #table1 body contains exactly 4 rows', async ({ page }) => {
    const table = page.locator('#table1');
    const bodyRows = table.locator('tbody tr');

    const rowCount = await bodyRows.count();
    expect(rowCount).toBe(4);
  });

  test('should verify row contains email jsmith@gmail.com in same row as last name Smith', async ({ page }) => {
    const table = page.locator('#table1');
    const tableRows = table.locator('tbody tr');

    let foundMatchingRow = false;
    const rowCount = await tableRows.count();

    for (let i = 0; i < rowCount; i++) {
      const row = tableRows.nth(i);
      const rowText = await row.textContent();

      if (rowText?.includes('Smith') && rowText?.includes('jsmith@gmail.com')) {
        foundMatchingRow = true;

        const lastNameCell = row.locator('td').nth(0);
        const emailCell = row.locator('td').nth(2);

        await expect(lastNameCell).toContainText('Smith');
        await expect(emailCell).toContainText('jsmith@gmail.com');
        break;
      }
    }

    expect(foundMatchingRow).toBe(true);
  });
});
